questionvariables.text:
/* Design: points inside, on or outside a circle by Pythagoras, with trap points. Entries [C, r, points, categories, [sum-trap row, square-trap row]]; category 1 inside, 2 on, 3 outside. The chapter's own circles ((-2, 4), 10) and ((1, -3), 17) are not used. Source: adapted from SMP AS/A2 Core 1, Chapter 7, A2 and A6. */
q21: [[[4,-3],13,[[-11,5],[12,6],[-1,9],[-6,-14]],[3,1,2,3],[2,4]],[[-1,-4],5,[[5,-3],[2,0],[-5,-2],[-5,0]],[3,2,1,3],[3,4]],[[3,0],5,[[6,4],[0,-3],[8,2],[7,4]],[2,1,3,3],[2,4]],[[1,2],13,[[-7,10],[-12,3],[-10,-8],[6,-10]],[1,3,3,2],[1,3]],[[2,3],10,[[-8,4],[6,-6],[8,11],[10,12]],[3,1,2,3],[2,4]],[[-3,2],13,[[-6,-9],[-3,4],[-15,11],[-8,-10]],[1,1,3,2],[1,3]],[[-3,2],13,[[10,4],[9,7],[9,9],[6,9]],[3,2,3,1],[4,3]],[[5,2],5,[[9,-2],[8,-1],[2,6],[0,-1]],[3,1,2,3],[2,1]],[[2,-3],10,[[-8,-2],[11,-1],[8,-11],[9,-12]],[3,1,2,3],[2,4]],[[-3,-2],5,[[0,-6],[1,-6],[-8,-1],[-6,-5]],[2,3,3,1],[4,2]]];
ix: 1+rand(10);
C: q21[ix][1]; r: q21[ix][2]; P: q21[ix][3]; cats: q21[ix][4]; trs: q21[ix][5][1]; trq: q21[ix][5][2];
dx: makelist(abs(P[k][1]-C[1]), k, 1, 4);
dy: makelist(abs(P[k][2]-C[2]), k, 1, 4);
d2: makelist(dx[k]^2+dy[k]^2, k, 1, 4);
keys: ["in","on","out"];
kyl: makelist(keys[cats[k]], k, 1, 4);
/* row type: 1 on the circle, 2 sum-trap (inside), 3 square-trap (outside), 4 plain */
ty: makelist(if is(cats[k]=2) then 1 else if is(k=trs) then 2 else if is(k=trq) then 3 else 4, k, 1, 4);
/* diagnostic answer per row: on-row inside; sum-trap outside; square-trap inside; plain row the opposite side */
dg: makelist(if is(ty[k]=1) then "in" else if is(ty[k]=2) then "out" else if is(ty[k]=3) then "in" else if is(kyl[k]="in") then "out" else "in", k, 1, 4);
/* generic wrong answer per row (tests) */
gw: makelist(if is(ty[k]=1) then "out" else "on", k, 1, 4);
mko(c) := [["in",is(c=1),"inside the circle"],["on",is(c=2),"on the circle"],["out",is(c=3),"outside the circle"]];
o1: mko(cats[1]); o2: mko(cats[2]); o3: mko(cats[3]); o4: mko(cats[4]);
ta1: kyl[1]; ta2: kyl[2]; ta3: kyl[3]; ta4: kyl[4];
